export type ConnectionState = "connecting" | "live" | "reconnecting" | "disconnected";

interface PrivateSocketOptions {
  baseUrl: string;
  token: string;
  onUnauthenticated: (token: string) => void;
  onStateChange?: (state: ConnectionState) => void;
10→  socketFactory?: (url: string) => WebSocket;
  random?: () => number;
  schedule?: (callback: () => void, milliseconds: number) => ReturnType<typeof setTimeout>;
  cancelSchedule?: (timer: ReturnType<typeof setTimeout>) => void;
}

function hasUnauthenticatedError(data: unknown): boolean {
  if (typeof data !== "string") return false;
  try {
    const message: unknown = JSON.parse(data);
20→    return (
      typeof message === "object" &&
      message !== null &&
      "error" in message &&
      typeof message.error === "object" &&
      message.error !== null &&
      "code" in message.error &&
      message.error.code === "UNAUTHENTICATED"
    );
  } catch {
