  if (typeof candidate.code !== "string") return null;
  return new ApiError(
    candidate.code,
    typeof candidate.message === "string" ? candidate.message : "La operación fue rechazada.",
    isRecord(candidate.details) ? candidate.details : undefined,
    status,
  );
}

async function body(response: Response): Promise<unknown> {
  try {
    return await response.json();
  } catch {
    return null;
  }
}

function isSession(value: unknown): value is Session {
  if (!isRecord(value)) return false;
  return (
    typeof value.token === "string" &&
    value.token.length > 0 &&
    typeof value.expiresAt === "string" &&
    !Number.isNaN(Date.parse(value.expiresAt))
  );
}

const CHECKSUM_ADDRESS = /^0x[0-9a-fA-F]{40}$/;

function parseDepositAddress(value: unknown, requestedAsset: Asset): DepositAddress | null {
  if (!isRecord(value)) return null;
  if (
    value.asset !== requestedAsset ||
    typeof value.address !== "string" ||
    !CHECKSUM_ADDRESS.test(value.address)
  ) {
    return null;
  }
  if (value.network !== undefined && value.network !== "sepolia") return null;
  if (value.chainId !== undefined && value.chainId !== "11155111") return null;
  if (requestedAsset === "USDC" && (
    typeof value.tokenAddress !== "string" || !CHECKSUM_ADDRESS.test(value.tokenAddress)
  )) return null;
  return {
    asset: requestedAsset,
    address: value.address,
    network: "sepolia",
    chainId: "11155111",
    ...(requestedAsset === "USDC" ? { tokenAddress: value.tokenAddress as string } : {}),
  };
}

export class ApiClient {
  private readonly baseUrl: string;
  private readonly fetchImpl: typeof fetch;
  private readonly onUnauthenticated: (token: string) => void;

  constructor(options: ApiClientOptions) {
    this.baseUrl = options.baseUrl.replace(/\/+$/, "");
    this.fetchImpl = options.fetchImpl ?? fetch;
    this.onUnauthenticated = options.onUnauthenticated;
  }

  async login(email: string, password: string): Promise<Session> {
    const response = await this.request("/api/v1/auth/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });
    if (!isSession(response)) throw new UnexpectedResponseError();
    return response;
  }

  async depositAddress(asset: Asset, token: string, signal?: AbortSignal): Promise<DepositAddress> {
    const response = await this.request(
      `/api/v1/deposit-address?asset=${asset}`,
      {
        signal,
        headers: { Authorization: `Bearer ${token}` },
      },
      token,
    );
    const parsed = parseDepositAddress(response, asset);
    if (!parsed) throw new UnexpectedResponseError();
    return parsed;
  }

  async invalidateRemoteSession(token: string): Promise<void> {
    try {
      await this.request("/api/v1/auth/logout", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
      });
    } catch {
      // Local logout must complete even when the server is unreachable or the token expired.
    }
  }

  private async request(path: string, init: RequestInit, authenticatedToken?: string): Promise<unknown> {
    let response: Response;
    try {
      response = await this.fetchImpl(`${this.baseUrl}${path}`, init);
    } catch (error) {
      if (error instanceof Error && error.name === "AbortError") throw error;
      throw new NetworkError();
    }

    const payload = response.status === 204 ? null : await body(response);
    if (response.ok) return payload;

    const apiError = parseApiError(payload, response.status);
    if (authenticatedToken && response.status === 401 && apiError?.code === "UNAUTHENTICATED") {
      this.onUnauthenticated(authenticatedToken);
    }
    throw apiError ?? new UnexpectedResponseError();
  }
}

export function validationIssues(error: ApiError): ValidationIssue[] {
  const raw = error.details?.issues;
  if (!Array.isArray(raw)) return [];
  return raw.flatMap((issue): ValidationIssue[] => {
    if (typeof issue === "string") return [{ field: "form", message: issue }];
    if (!isRecord(issue) || typeof issue.message !== "string" || issue.message.length === 0) return [];
    const fieldValue = issue.field ?? issue.path;
    const path = Array.isArray(fieldValue)
      ? fieldValue.filter((part): part is string => typeof part === "string").at(-1)
      : fieldValue;
    const leaf = typeof path === "string" ? path.split(/[/.]/).filter(Boolean).at(-1) : undefined;
    const field: ValidationIssue["field"] = leaf === "email" || leaf === "password" || leaf === "body"
      ? leaf
      : "form";
    return [{ field, message: issue.message }];
  });
}

