    });
    const cleared = jest.fn();
    const manager = new SessionManager(store, cleared);
    await manager.establish("sesion-A");

90→    const establishNew = manager.establish("sesion-B");
    await Promise.resolve();
    // Even a caller that omits the context captures session A at invocation time.
