import { ApiClient, NetworkError } from "./api";
import { SessionManager } from "./session";

function response(status: number, payload: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: jest.fn().mockResolvedValue(payload),
  } as unknown as Response;
}

describe("contrato API mobile", () => {
  test("AT-11-01-01 login usa el contrato HTTP exacto", async () => {
    const fetchImpl = jest.fn().mockResolvedValue(response(200, {
      token: "opaco",
      expiresAt: "2030-01-01T00:00:00.000Z",
    }));
    const api = new ApiClient({ baseUrl: "http://api.test/", fetchImpl, onUnauthenticated: jest.fn() });
    await expect(api.login("trader@example.com", "secreta")).resolves.toEqual({
      token: "opaco",
      expiresAt: "2030-01-01T00:00:00.000Z",
    });
    expect(fetchImpl).toHaveBeenCalledWith("http://api.test/api/v1/auth/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: "trader@example.com", password: "secreta" }),
    });
  });

  test("AT-11-01-04 conserva el code estable del envelope", async () => {
    const api = new ApiClient({
      baseUrl: "http://api.test",
      fetchImpl: jest.fn().mockResolvedValue(response(401, {
        error: { code: "INVALID_CREDENTIALS", message: "Las credenciales son inválidas.", details: {} },
      })),
      onUnauthenticated: jest.fn(),
    });
    await expect(api.login("a@b.co", "mal")).rejects.toMatchObject({ code: "INVALID_CREDENTIALS" });
  });

  test("AT-11-01-05/14 varios 401 protegidos comparten una limpieza singleton", async () => {
    const store = {
      readToken: jest.fn().mockResolvedValue(null),
      saveToken: jest.fn().mockResolvedValue(undefined),
      clearToken: jest.fn().mockResolvedValue(undefined),
    };
