import type { RawData, WebSocket } from "ws";
import type { AuthService } from "./auth/service.js";
import { AppError, errorBody, validationIssue } from "./errors.js";

export const WS_AUTH_TIMEOUT_MS = 10_000;
export const WS_HEARTBEAT_INTERVAL_MS = 30_000;
export const WS_PONG_TIMEOUT_MS = 10_000;
export const WS_UNAUTHENTICATED_CLOSE_CODE = 4001;

export interface WebSocketSessionOptions {
  authTimeoutMs?: number;
  heartbeatIntervalMs?: number;
  pongTimeoutMs?: number;
  now?: () => Date;
}

interface ClientMessage {
  type?: unknown;
  token?: unknown;
}

/**
 * Attach the minimal private-session protocol used by the mobile authentication flow.
 * Domain subscriptions intentionally remain unavailable until their backing epics exist.
 */
export function attachWebSocketSession(
  socket: WebSocket,
  auth: AuthService,
  options: WebSocketSessionOptions = {},
): void {
  const authTimeoutMs = options.authTimeoutMs ?? WS_AUTH_TIMEOUT_MS;
  const heartbeatIntervalMs = options.heartbeatIntervalMs ?? WS_HEARTBEAT_INTERVAL_MS;
  const pongTimeoutMs = options.pongTimeoutMs ?? WS_PONG_TIMEOUT_MS;
  const now = options.now ?? (() => new Date());
  let authenticated = false;
  let terminating = false;
  let heartbeatTimer: NodeJS.Timeout | undefined;
  let pongTimer: NodeJS.Timeout | undefined;
  let expirationTimer: NodeJS.Timeout | undefined;

  const authenticationTimer = setTimeout(() => {
    rejectUnauthenticated();
  }, authTimeoutMs);
  authenticationTimer.unref();

  const clearTimers = (): void => {
    clearTimeout(authenticationTimer);
    if (heartbeatTimer) clearInterval(heartbeatTimer);
    if (pongTimer) clearTimeout(pongTimer);
    if (expirationTimer) clearTimeout(expirationTimer);
  };

  const close = (code: number, reason: string): void => {
    if (terminating) return;
    terminating = true;
    clearTimers();
    if (socket.readyState === 0 || socket.readyState === 1) socket.close(code, reason);
  };

  const send = (payload: unknown): void => {
    if (socket.readyState === 1) socket.send(JSON.stringify(payload));
  };

  function rejectUnauthenticated(): void {
    if (terminating) return;
    send(errorBody(new AppError("UNAUTHENTICATED", "Se requiere una credencial válida.")));
    close(WS_UNAUTHENTICATED_CLOSE_CODE, "Unauthenticated");
  }

  const startHeartbeat = (): void => {
    heartbeatTimer = setInterval(() => {
      if (terminating || socket.readyState !== 1) return;
      send({ type: "ping" });
      if (pongTimer) clearTimeout(pongTimer);
      pongTimer = setTimeout(() => close(1001, "Heartbeat timeout"), pongTimeoutMs);
      pongTimer.unref();
    }, heartbeatIntervalMs);
    heartbeatTimer.unref();
  };

  const startExpirationTimer = (expiresAt: string): void => {
    const remainingMs = Date.parse(expiresAt) - now().getTime();
    expirationTimer = setTimeout(rejectUnauthenticated, Math.max(0, remainingMs));
    expirationTimer.unref();
  };

  socket.on("message", (data: RawData, isBinary: boolean) => {
    if (terminating) return;
    const message = isBinary ? undefined : parseClientMessage(data);

    if (!authenticated) {
      if (!isAuthenticationMessage(message)) {
        rejectUnauthenticated();
        return;
      }
      try {
        const session = auth.authenticateSession(`Bearer ${message.token}`);
        authenticated = true;
        clearTimeout(authenticationTimer);
        send({ type: "authenticated" });
        startExpirationTimer(session.expiresAt);
        startHeartbeat();
      } catch {
        rejectUnauthenticated();
      }
      return;
    }

    if (message?.type === "pong") {
      if (pongTimer) clearTimeout(pongTimer);
      pongTimer = undefined;
      return;
    }

    // Trading, balance and withdrawal subscriptions depend on epics deliberately outside
    // this stage. Keep the socket valid while returning the canonical WS error envelope.
    send(errorBody(validationIssue("message", "El mensaje o canal no está disponible")));
  });

  socket.once("close", clearTimers);

