#!/usr/bin/env python3
"""Helpers de UI/adb para la rúbrica mobile. No modifica el SUT."""
from __future__ import annotations

import json
import os
import re
import subprocess
import sys
import time
from pathlib import Path
from xml.etree import ElementTree as ET

SERIAL = os.environ.get("ANDROID_SERIAL", "emulator-5554")
EVID = Path(os.environ.get("EVAL_EVID", "/private/tmp/eval-rubrica-mobile-pre-piloto-2b-p1-20260907-144419/evidencia"))
EVID.mkdir(parents=True, exist_ok=True)
API = os.environ.get("EXCHANGE_API_URL", "http://127.0.0.1:3203")
RPC = os.environ.get("EVAL_RPC_URL", "http://127.0.0.1:8545")
USDC = os.environ.get("EVAL_USDC_ADDRESS", "0xe7f1725E7734CE288F8367e1Bb143E90bb3F0512")
ANVIL0 = "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266"


def adb(*args: str, check: bool = True, timeout: int = 60) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["adb", "-s", SERIAL, *args],
        check=check,
        capture_output=True,
        timeout=timeout,
        text=True,
    )


def adb_bytes(*args: str, timeout: int = 60) -> bytes:
    return subprocess.check_output(["adb", "-s", SERIAL, *args], timeout=timeout)


def dump_xml() -> str:
    adb("shell", "uiautomator", "dump", "/sdcard/ui.xml")
    return adb("shell", "cat", "/sdcard/ui.xml").stdout


def parse_nodes(xml: str) -> list[dict]:
    nodes = []
    # uiautomator dump is a single <hierarchy> with <node> elements
    try:
        root = ET.fromstring(xml)
    except ET.ParseError:
        return nodes
    for el in root.iter("node"):
        bounds = el.attrib.get("bounds", "")
        m = re.match(r"\[(\d+),(\d+)\]\[(\d+),(\d+)\]", bounds)
        box = tuple(map(int, m.groups())) if m else None
        nodes.append(
            {
                "text": el.attrib.get("text") or "",
                "desc": el.attrib.get("content-desc") or "",
                "cls": el.attrib.get("class") or "",
                "clickable": el.attrib.get("clickable") == "true",
                "enabled": el.attrib.get("enabled") == "true",
                "bounds": box,
                "hint": el.attrib.get("hint") or "",
            }
        )
    return nodes


def texts(xml: str | None = None) -> list[str]:
    xml = xml or dump_xml()
    return [n["text"] for n in parse_nodes(xml) if n["text"]]


def has_text(needle: str, xml: str | None = None) -> bool:
    xml = xml or dump_xml()
    return any(needle in (n["text"] + " " + n["desc"]) for n in parse_nodes(xml))


def wait_text(needle: str, timeout: float = 30.0, interval: float = 0.8) -> str:
    deadline = time.time() + timeout
    last = ""
    while time.time() < deadline:
        last = dump_xml()
        if has_text(needle, last):
            return last
        time.sleep(interval)
    raise TimeoutError(f"no apareció {needle!r} en {timeout}s. textos={texts(last)[:20]}")


def wait_any(needles: list[str], timeout: float = 30.0) -> tuple[str, str]:
    deadline = time.time() + timeout
    last = ""
    while time.time() < deadline:
        last = dump_xml()
        for n in needles:
            if has_text(n, last):
                return n, last
        time.sleep(0.8)
    raise TimeoutError(f"no apareció ninguno de {needles}. textos={texts(last)[:20]}")


def center(box: tuple[int, int, int, int]) -> tuple[int, int]:
    x1, y1, x2, y2 = box
    return (x1 + x2) // 2, (y1 + y2) // 2


def tap_xy(x: int, y: int) -> None:
    adb("shell", "input", "tap", str(x), str(y))


def tap_node(pred, xml: str | None = None) -> bool:
    xml = xml or dump_xml()
    for n in parse_nodes(xml):
        if n["bounds"] and pred(n):
            x, y = center(n["bounds"])
            tap_xy(x, y)
            return True
    return False


def tap_desc(desc: str, xml: str | None = None) -> None:
    xml = xml or dump_xml()
    if not tap_node(lambda n: n["desc"] == desc or desc in n["desc"], xml):
        raise RuntimeError(f"no tap desc={desc!r} textos={[(n['text'], n['desc']) for n in parse_nodes(xml) if n['text'] or n['desc']][:15]}")


def tap_text(text: str, xml: str | None = None, exact: bool = True) -> None:
    xml = xml or dump_xml()
    pred = (lambda n: n["text"] == text) if exact else (lambda n: text in n["text"])
    if not tap_node(pred, xml):
        raise RuntimeError(f"no tap text={text!r}")


def screenshot(name: str) -> Path:
    path = EVID / f"{name}.png"
    data = adb_bytes("exec-out", "screencap", "-p")
    path.write_bytes(data)
    return path


def save_dump(name: str, xml: str | None = None) -> Path:
    xml = xml or dump_xml()
    path = EVID / f"{name}.xml"
    path.write_text(xml)
    return path


def keyevent(name_or_code) -> None:
    adb("shell", "input", "keyevent", str(name_or_code))


def hide_keyboard() -> None:
    keyevent("KEYCODE_BACK")
    time.sleep(0.4)


def input_text(text: str) -> None:
    """Escribe texto mezclando `input text` (alfanum) y keyevents para @ y símbolos."""
    buf: list[str] = []

    def flush() -> None:
        if not buf:
            return
        chunk = "".join(buf)
        # Android `input text` usa %s para espacio
        chunk_esc = chunk.replace(" ", "%s")
        # pasar como un único argumento a adb shell
        adb("shell", "input", "text", chunk_esc)
        buf.clear()

    specials = {
        "@": "KEYCODE_AT",
        " ": "KEYCODE_SPACE",
        ".": None,  # input text accepts dot
        "-": None,
        "_": None,
    }
    for ch in text:
        if ch.isalnum() or ch in ".-_":
            buf.append(ch)
        else:
            flush()
            if ch == "@":
                keyevent("KEYCODE_AT")
            elif ch == " ":
                keyevent("KEYCODE_SPACE")
            else:
                # último recurso
                adb("shell", "input", "text", ch)
    flush()


def clear_field() -> None:
    # seleccionar todo y borrar
    adb("shell", "input", "keyevent", "KEYCODE_MOVE_END")
    adb("shell", "input", "keyevent", "--longpress", "KEYCODE_DEL")
    # extra deletes
    for _ in range(40):
        adb("shell", "input", "keyevent", "KEYCODE_DEL")


def home() -> None:
    keyevent("KEYCODE_HOME")


def force_stop_expo() -> None:
    adb("shell", "am", "force-stop", "host.exp.exponent")


def relaunch() -> str:
    script = os.environ["CMD_RELANZAR_APP"]
    out = subprocess.run(["bash", script], check=True, capture_output=True, text=True, timeout=90)
    return out.stdout + out.stderr


def foreground_expo() -> None:
    adb(
        "shell",
        "am",
        "start",
        "-n",
        "host.exp.exponent/.experience.ExperienceActivity",
        check=False,
    )


def curl_json(method: str, path: str, body=None, token: str | None = None, timeout: int = 20):
    cmd = ["curl", "-sS", "-X", method, f"{API}{path}", "-H", "Content-Type: application/json", "-w", "\n%{http_code}"]
    if token:
        cmd[5:5] = ["-H", f"Authorization: Bearer {token}"]
    if body is not None:
        cmd.extend(["--data", json.dumps(body)])
    raw = subprocess.check_output(cmd, timeout=timeout, text=True)
    *body_lines, code = raw.rsplit("\n", 1)
    payload = "\n".join(body_lines)
    try:
        parsed = json.loads(payload) if payload else None
    except json.JSONDecodeError:
        parsed = payload
    return int(code), parsed


def db_sql(sql: str, write: bool = False):
    ro = "false" if write else "true"
    script = f"""
const {{DatabaseSync}}=require('node:sqlite');
const db=new DatabaseSync('/repo/data/exchange.sqlite', {{readOnly: {ro}}});
const r=db.prepare({json.dumps(sql)}).all();
console.log(JSON.stringify(r));
"""
    out = subprocess.check_output(["docker", "exec", "sut-2b", "node", "-e", script], text=True)
    return json.loads(out)


def db_run(sql: str):
    script = f"""
const {{DatabaseSync}}=require('node:sqlite');
const db=new DatabaseSync('/repo/data/exchange.sqlite');
const r=db.prepare({json.dumps(sql)}).run();
console.log(JSON.stringify(r));
"""
    out = subprocess.check_output(["docker", "exec", "sut-2b", "node", "-e", script], text=True)
    return json.loads(out)


def backend_logs(since: str = "2m") -> str:
    return subprocess.check_output(["docker", "logs", "--since", since, "sut-2b"], text=True, stderr=subprocess.STDOUT)


def rpc(method: str, params):
    raw = subprocess.check_output(
        [
            "curl",
            "-sS",
            "-X",
            "POST",
            RPC,
            "-H",
            "Content-Type: application/json",
            "--data",
            json.dumps({"jsonrpc": "2.0", "id": 1, "method": method, "params": params}),
        ],
        text=True,
    )
    return json.loads(raw)


def eip55(addr: str) -> str:
    addr = addr.lower().replace("0x", "")
    digest = subprocess.check_output(
        [
            "node",
            "-e",
            "const k=require('/tmp/eval-tools/node_modules/keccak'); const a=process.argv[1]; process.stdout.write(k('keccak256').update(a).digest('hex'));",
            addr,
        ],
        text=True,
    )
    out = "0x"
    for i, ch in enumerate(addr):
        out += ch.upper() if ch.isalpha() and int(digest[i], 16) >= 8 else ch
    return out


def decode_qr(png_path: str) -> str:
    p = subprocess.run(["zbarimg", "-q", "--raw", png_path], capture_output=True, text=True)
    return (p.stdout or "").strip()


def logcat_clear() -> None:
    adb("logcat", "-c", check=False)


def logcat_dump(grep: str | None = None, count: int = 400) -> str:
    out = adb("logcat", "-d", "-t", str(count), check=False).stdout
    if grep:
        return "\n".join(line for line in out.splitlines() if grep.lower() in line.lower())
    return out


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "texts"
    if cmd == "texts":
        xml = dump_xml()
        for t in texts(xml):
            print(t)
    elif cmd == "dump":
        print(dump_xml())
    elif cmd == "shot":
        print(screenshot(sys.argv[2]))
    else:
        raise SystemExit(f"unknown {cmd}")

