    return (p.stdout or "").strip()


def logcat_clear() -> None:
    adb("logcat", "-c", check=False)


def logcat_dump(grep: str | None = None, count: int = 400) -> str:
    out = adb("logcat", "-d", "-t", str(count), check=False).stdout
    if grep:
        return "\n".join(line for line in out.splitlines() if grep.lower() in line.lower())
    return out


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "texts"
    if cmd == "texts":
        xml = dump_xml()
        for t in texts(xml):
            print(t)
    elif cmd == "dump":
        print(dump_xml())
    elif cmd == "shot":
        print(screenshot(sys.argv[2]))
    else:
        raise SystemExit(f"unknown {cmd}")

