const configuredUrl = process.env.EXPO_PUBLIC_API_URL?.trim();

export const API_BASE_URL = (configuredUrl || "http://localhost:3000").replace(/\/+$/, "");

export function websocketUrl(baseUrl: string): string {
  const url = new URL(baseUrl);
